const raw=await tools.Read({file_path:"/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/31.csv"});
if(typeof raw!=="string") throw new Error("Expected CSV text");
const lines=raw.trim().split("\n");
const rad=d=>d*Math.PI/180;
const rows=lines.slice(1).map(line=>{const [truckId,at,lat,lon,engineOn,odometer]=line.split(",");const a=Math.sin(rad(Number(lat)-30.1827)/2)**2+Math.cos(rad(30.1827))*Math.cos(rad(Number(lat)))*Math.sin(rad(Number(lon)+96.9364)/2)**2;return {line,truckId,at,meters:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};});
const window=rows.filter(r=>r.at>="2026-08-12T18:11:35Z"&&r.at<="2026-08-12T18:31:35Z").sort((a,b)=>a.meters-b.meters);
text({source:"telematics/31.csv",rowCount:rows.length,windowRows:window.length,within3000m:window.filter(r=>r.meters<=3000).length,nearestWindowRows:window.slice(0,5)});
text({source:"telematics/31.csv",truck34Rows:rows.filter(r=>r.truckId==="34").map(r=>r.line)});
text({source:"telematics/31.csv",nearestAllDay:rows.slice().sort((a,b)=>a.meters-b.meters).slice(0,5)});
